'use client'

import { useEffect, useState } from 'react'

export function InventoryClient() {
  const [inventory, setInventory] = useState<{
    count: number
    price: string
  } | null>(null)

  useEffect(() => {
    fetch('/api/inventory')
      .then((res) => res.json())
      .then(setInventory)
  }, [])

  if (!inventory) {
    return <p>Loading availability…</p>
  }

  return (
    <>
      <p>{inventory.count} in stock</p>
      <p>Price: ${inventory.price}</p>
    </>
  )
}

